// Checks that the decoder generated by reflection, decode<T>, gives exactly the
// same result as the hand-written decoders in itch.hpp, on all five messages.
#include "itch.hpp"
#include "reflect_decode.hpp"
#include <cstdint>
#include <iostream>
#include <string>

static int failures = 0;

// Compare two numbers; print a line only when they differ.
void check_num(const std::string& name, std::uint64_t got, std::uint64_t want) {
    if (got != want) {
        std::cout << "FAIL " << name << ": got " << got << ", want " << want << '\n';
        ++failures;
    }
}

// Compare two pieces of text; print a line only when they differ.
void check_text(const std::string& name, const std::string& got, const std::string& want) {
    if (got != want) {
        std::cout << "FAIL " << name << ": got '" << got << "', want '" << want << "'\n";
        ++failures;
    }
}

// The five fields every message starts with. "got" is the generated decoder,
// "want" is the hand-written one.
template <class Message>
void check_common(const std::string& prefix, const Message& got, const Message& want) {
    check_text(prefix + ".message_type", std::string(1, got.message_type), std::string(1, want.message_type));
    check_num(prefix + ".stock_locate", got.stock_locate, want.stock_locate);
    check_num(prefix + ".tracking_number", got.tracking_number, want.tracking_number);
    check_num(prefix + ".timestamp", got.timestamp, want.timestamp);
    check_num(prefix + ".order_reference", got.order_reference, want.order_reference);
}

void test_add_order() {
    const std::uint8_t msg[36] = {
        0x41,                                            // message type 'A'
        0x00, 0x01,                                      // stock locate = 1
        0x00, 0x02,                                      // tracking number = 2
        0x00, 0x00, 0x00, 0x00, 0x03, 0xE8,              // timestamp = 1000
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x2A,  // order reference = 42
        0x42,                                            // side 'B'
        0x00, 0x00, 0x00, 0x64,                          // shares = 100
        0x41, 0x41, 0x50, 0x4C, 0x20, 0x20, 0x20, 0x20,  // stock "AAPL    "
        0x00, 0x16, 0xE3, 0x60                           // price = 1500000
    };
    AddOrder got = decode<AddOrder>(msg);
    AddOrder want = decode_add_order(msg);
    check_common("add_order", got, want);
    check_text("add_order.side", std::string(1, got.side), std::string(1, want.side));
    check_num("add_order.shares", got.shares, want.shares);
    check_text("add_order.stock", std::string(got.stock.begin(), got.stock.end()),
               std::string(want.stock.begin(), want.stock.end()));
    check_num("add_order.price", got.price, want.price);
}

void test_order_executed() {
    const std::uint8_t msg[31] = {
        0x45,                                            // message type 'E'
        0x00, 0x01,                                      // stock locate = 1
        0x00, 0x02,                                      // tracking number = 2
        0x00, 0x00, 0x00, 0x00, 0x03, 0xE8,              // timestamp = 1000
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x2A,  // order reference = 42
        0x00, 0x00, 0x00, 0x32,                          // executed shares = 50
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x07   // match number = 7
    };
    OrderExecuted got = decode<OrderExecuted>(msg);
    OrderExecuted want = decode_order_executed(msg);
    check_common("order_executed", got, want);
    check_num("order_executed.executed_shares", got.executed_shares, want.executed_shares);
    check_num("order_executed.match_number", got.match_number, want.match_number);
}

void test_order_cancel() {
    const std::uint8_t msg[23] = {
        0x58,                                            // message type 'X'
        0x00, 0x01,                                      // stock locate = 1
        0x00, 0x02,                                      // tracking number = 2
        0x00, 0x00, 0x00, 0x00, 0x03, 0xE8,              // timestamp = 1000
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x2A,  // order reference = 42
        0x00, 0x00, 0x00, 0x19                           // cancelled shares = 25
    };
    OrderCancel got = decode<OrderCancel>(msg);
    OrderCancel want = decode_order_cancel(msg);
    check_common("order_cancel", got, want);
    check_num("order_cancel.cancelled_shares", got.cancelled_shares, want.cancelled_shares);
}

void test_order_delete() {
    const std::uint8_t msg[19] = {
        0x44,                                            // message type 'D'
        0x00, 0x01,                                      // stock locate = 1
        0x00, 0x02,                                      // tracking number = 2
        0x00, 0x00, 0x00, 0x00, 0x03, 0xE8,              // timestamp = 1000
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x2A   // order reference = 42
    };
    OrderDelete got = decode<OrderDelete>(msg);
    OrderDelete want = decode_order_delete(msg);
    check_common("order_delete", got, want);
}

void test_order_replace() {
    const std::uint8_t msg[35] = {
        0x55,                                            // message type 'U'
        0x00, 0x01,                                      // stock locate = 1
        0x00, 0x02,                                      // tracking number = 2
        0x00, 0x00, 0x00, 0x00, 0x03, 0xE8,              // timestamp = 1000
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x2A,  // original order reference = 42
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x2B,  // new order reference = 43
        0x00, 0x00, 0x00, 0xC8,                          // shares = 200
        0x00, 0x16, 0xE7, 0x48                           // price = 1501000
    };
    OrderReplace got = decode<OrderReplace>(msg);
    OrderReplace want = decode_order_replace(msg);
    check_common("order_replace", got, want);
    check_num("order_replace.new_order_reference", got.new_order_reference, want.new_order_reference);
    check_num("order_replace.shares", got.shares, want.shares);
    check_num("order_replace.price", got.price, want.price);
}

int main() {
    test_add_order();
    test_order_executed();
    test_order_cancel();
    test_order_delete();
    test_order_replace();

    if (failures == 0) std::cout << "all tests passed\n";
    return failures == 0 ? 0 : 1;
}
